interface ContentChunk { offset: number; byteLength: number; storedOffset: number; storedByteLength: number; sha256: string; compressed: boolean; ordinal?: number }
function parseContentChunkIndex(text: string): { chunks: ContentChunk[]; firstOrdinal: number } {
  const value = JSON.parse(text);
  const chunks = Array.isArray(value) ? value : value?.chunks;
  const firstOrdinal = Array.isArray(value) ? 0 : value?.firstOrdinal;
  if (!Array.isArray(chunks) || !Number.isSafeInteger(firstOrdinal) || firstOrdinal < 0 || !Number.isSafeInteger(firstOrdinal + chunks.length)) throw new Error('content_integrity_error');
  return { chunks, firstOrdinal };
}
