        const object=this.readMetadataInSnapshot(id,undefined,false,(batchId,inputContentId,saved)=>{
          result.reviewControls.push({batchId,inputContentId});contents.add(inputContentId);
          if(!saved.projectIds)for(const root of saved.manifest.projects as string[])if(!result.locations.some(value=>value.root===root))result.locations.push({root,projectIds:this.rows('SELECT DISTINCT project_id FROM project_locations WHERE device_id=? AND root_path=?',[this.deviceId,root]).map(row=>String(row.project_id))});
        });
