      const value=request.state,current=value.type==='analysis'?this.readAnalysisState(value.projectId,value.namespace,value.key):this.readStrategyState(value.projectId),choice=this.stateImportChoice(value),binding=this.rows('SELECT object_id FROM migration_items WHERE source_identity=? AND source_key=?',[source.identity,source.key])[0];
