    if(complete){this.db.run('INSERT OR REPLACE INTO object_search(rowid,terms) VALUES(?,?)',[rowid,contentTerms || '']);this.generationSearchObjectIds?.add(object.objectId);return;}
    const hostReview = object.kind === 'review_batch' && this.rows('SELECT 1 FROM learning_review_controls WHERE batch_id=?', [object.objectId]).length > 0;
    let data = hostReview ? agentReadableObject({ ...object, projection: { ...object.projection, hostReview: true } }).data : object.data;
