      return {object,terms:indexTokens(canonical({...data,content:decoded.get('header')})),snapshot:prepareContentPublication({bytes:canonical(this.snapshot(object)),mimeType:'application/json',encoding:'utf8'}),contents:request.contents,serialized:JSON.stringify(prepared.result),notification:this.prepareFlowNotification(prepared,actorId,time,request.notificationConfigurationReady,request.projectedRuns)};
