      artifacts=this.maintenanceCompute?.prepareAgentLaunchArtifacts || this.agentLaunchCompute?.artifacts,
      step=this.maintenanceCompute?.prepareAgentLaunchStep || this.agentLaunchCompute?.step,
      project=this.maintenanceCompute?.projectRunInputsResult || this.runInputsCompute?.result;
    if(!select || !artifacts || !step || !project)return Promise.reject(new Error('content_preparation_compute_required'));
    let budget=owned?.interactionBudget || options.interactionBudget || currentInteractionBudget(),preflight:AgentRunPreparationPreflight={},backup:string|undefined,backupCaptured=false;
    let resumeClaim:{state:RunState;owner:NonNullable<AgentLaunchOptions['deliveryOwner']>;receipt:WriteReceipt}|undefined;
    const publisherKeys=new Set<string>();
    if(owned?.flowRole)publisherKeys.add(canonical(['flow-role',projectId,owned.flowRole.flowId,owned.flowRole.loopId,owned.flowRole.role,owned.flowRole.attempt]));
    if(owned?.launchSlotId)publisherKeys.add(canonical(['run-allocation','slot',owned.launchSlotScope || 'project',owned.launchSlotScope==='global'?null:projectId,owned.launchSlotId]));
    if(owned?.launchIntentId)publisherKeys.add(canonical(['run-allocation','intent','project',projectId,owned.launchIntentId]));
