      const batch=tokens.slice(offset,offset+128);for(const token of batch)this.retiredRunObserverParserTokens.add(token);
      try{if(!release)throw new Error('content_preparation_compute_required');await release({...this.dataWriteDatabaseIdentity(),tokens:batch});for(const token of batch){this.retiredRunObserverParserTokens.delete(token);this.runObserverParserTokens.delete(token);this.reportedRunObserverParserTokens.delete(token);}}
