    if(Number(head?.revision)!==receipt.revision){const snapshot=this.rows('SELECT r.content_id,c.sha256 FROM object_revisions r JOIN contents c ON c.id=r.content_id WHERE r.object_id=? AND r.revision=?',[receipt.objectId,receipt.revision])[0];if(!snapshot)throw new Error('revision_missing');selection.revisions.push({objectId:receipt.objectId,revision:receipt.revision,contentId:String(snapshot.content_id),sha256:String(snapshot.sha256)});selection.contents.push(this.contentVerificationIdentity(String(snapshot.content_id)));}
    for(const [column,id] of Object.entries(state.data))if(typeof id==='string' && (column==='content_id' || column.endsWith('_content_id')))selection.contents.push(this.contentVerificationIdentity(id));
