        if(Number(head?.revision)!==receipt.revision){const snapshot=this.rows('SELECT r.content_id,c.sha256 FROM object_revisions r JOIN contents c ON c.id=r.content_id WHERE r.object_id=? AND r.revision=?',[receipt.objectId,receipt.revision])[0];if(!snapshot)throw new Error('revision_missing');selected.revisions.push({objectId:receipt.objectId,revision:receipt.revision,contentId:String(snapshot.content_id),sha256:String(snapshot.sha256)});selected.contents.push(this.contentVerificationIdentity(String(snapshot.content_id)));}
