  private stateWriteReservationChoice(header:StateWriteHeader):Record<string,SqlValue>|null {
    return header.reservation && header.type==='analysis'?this.stateImportChoice({type:'analysis',projectId:header.projectId,namespace:'external-refresh',key:header.key}):null;
  }
